from typing import Annotated, Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, StringConstraints

from app.ai.schemas import MAX_MENTOR_REPLY_LENGTH

MAX_MENTOR_MESSAGE_LENGTH = 4000
#: Earlier turns a client may send; older ones are its to drop.
MAX_MENTOR_HISTORY_TURNS = 12

#: Messages kept per conversation; older ones are dropped as new ones arrive.
#: Even, so the oldest kept message is always a user message.
MAX_STORED_MENTOR_MESSAGES = 200

MentorRole = Literal["user", "mentor"]
#: Generated by the client for each new user message and reused when that
#: message is retried, so a retry of an exchange that was already saved
#: returns the saved reply instead of being saved (and answered) twice.
MentorMessageId = Annotated[str, StringConstraints(pattern=r"^[A-Za-z0-9_-]{8,64}$")]
ProjectIdParam = Annotated[str, StringConstraints(min_length=1, max_length=64)]
#: What the mentor was given about the selected project, in addition to the
#: conversation itself.
MentorContextSource = Literal["project", "blueprint", "learning"]


class MentorTurnIn(BaseModel):
    model_config = ConfigDict(extra="forbid")

    role: MentorRole
    # Large enough for an earlier mentor reply sent back as history.
    content: Annotated[
        str, StringConstraints(strip_whitespace=True, min_length=1, max_length=MAX_MENTOR_REPLY_LENGTH)
    ]


class MentorChatRequest(BaseModel):
    """Mirrors features/mentor/types/mentor.ts::MentorChatRequest exactly.

    The client sends the earlier turns it wants considered; the exchange
    itself is saved to the caller's conversation for this context once a
    valid reply exists. Identity never comes from the body: the project is
    looked up for the authenticated user only.
    """

    model_config = ConfigDict(extra="forbid")

    messageId: MentorMessageId
    message: Annotated[
        str, StringConstraints(strip_whitespace=True, min_length=1, max_length=MAX_MENTOR_MESSAGE_LENGTH)
    ]
    #: None for general mentoring.
    projectId: Optional[ProjectIdParam] = None
    history: list[MentorTurnIn] = Field(default_factory=list, max_length=MAX_MENTOR_HISTORY_TURNS)


class MentorContextInfo(BaseModel):
    """What the reply was grounded in, so the client can show it."""

    projectId: Optional[str] = None
    projectName: Optional[str] = None
    sources: list[MentorContextSource]
    #: User-facing notes on project context that was unavailable.
    limitations: list[str]


class MentorReply(BaseModel):
    """Mirrors features/mentor/types/mentor.ts::MentorReply exactly."""

    #: The saved reply's id.
    messageId: str
    reply: str
    context: MentorContextInfo


class MentorMessageOut(BaseModel):
    """Mirrors features/mentor/types/mentor.ts::MentorStoredMessage exactly."""

    id: str
    role: MentorRole
    content: str
    #: Set on mentor messages.
    context: Optional[MentorContextInfo] = None
    createdAt: str


class MentorConversationOut(BaseModel):
    """Mirrors features/mentor/types/mentor.ts::MentorConversationHistory exactly."""

    #: None for general mentoring.
    projectId: Optional[str] = None
    #: Oldest first; empty when nothing has been saved yet.
    messages: list[MentorMessageOut]
